<script setup>import {onMounted,ref,onUnmounted} from 'vue';import client from '@/api/client';const board=ref({}),error=ref('');async function load(){try{board.value=(await client.get('/work-orders/board')).data.data}catch(e){error.value='Papan gagal dimuat.'}}let timer;onMounted(()=>{load();timer=setInterval(load,10000)});onUnmounted(()=>clearInterval(timer))</script><template><main><h1 class="text-2xl font-bold text-forest">Papan Antrian</h1><div v-if="error" class="service-alert">{{error}}</div><div class="grid gap-4 md:grid-cols-2 lg:grid-cols-4"><section v-for="(items,status) in board" :key="status" class="min-w-0"><h2 class="text-base font-bold text-forest text-capitalize">{{status}}</h2><RouterLink v-for="item in items" :key="item.id" :to="`/work-orders/${item.id}`" class="service-service-card mb-3 block p-4 text-decoration-none hover:border-forest">{{item.queue_number_display}}</RouterLink><p v-if="!items?.length" class="text-muted">Kosong</p></section></div></main></template>